class Complex {
  constructor(real=0, imag=0, infinite=false) {
    if (real === Infinity || imag === Infinity) {
      throw new Error("Use complex_infinity instead.");
    }
    this.real = real;
    this.imag = imag;
    this.infinite = infinite;
  }

  norm() {
    if (this.infinite) {
      return Infinity;
    }
    return Math.sqrt(this.real * this.real + this.imag * this.imag);
  }

  argument() {
    if (this.zero() || this.infinite) {
      throw new Error("Nonsensical argument");
    }
    return Math.atan2(this.imag, this.real);
  }

  normSquared() {
    if (this.infinite) {
      return Infinity;
    }
    return this.real * this.real + this.imag * this.imag;
  }

  unit() {
    if (this.zero() || this.infinite) {
      throw new Error("Nonsensical unit vector");
    }
    return this.times(1.0 / this.norm());
  }

  zero() {
    return this.norm() < 0.0000001;
  }

  conjugate() {
    if (this.infinite) {
      return complex_infinity;
    }
    return new Complex(this.real, -this.imag);
  }

  times(other) {
    if (other instanceof Complex) {
      if ((this.zero() && other.infinite) || (this.infinite && other.zero())) {
        throw new Error("Nonsensical complex number multiplication.");
      }
      if (this.infinite || other.infinite) {
        return complex_infinity;
      }
      return new Complex(
        this.real * other.real - this.imag * other.imag,
        this.real * other.imag + this.imag * other.real
      );
    } else {
      return this.times(new Complex(other, 0));
    }
  }

  over(other) {
    if (other instanceof Complex) {
      if ((this.infinite && other.infinite) || (this.zero() && other.zero())) {
        throw new Error("Nonsensical complex number division");
      }
      if (this.infinite || other.zero()) {
        return complex_infinity;
      }
      return this.times(other.conjugate()).times(1 / other.normSquared());
    } else {
      return this.over(new Complex(other, 0));
    }
  }

  plus(other) {
    if (this.infinite || other.infinite) {
      return complex_infinity;
    }
    return new Complex(
      this.real + other.real,
      this.imag + other.imag
    );
  }

  minus(other) {
    if (this.infinite && other.infinite) {
      throw new Error("Nonsensical complex number subtraction.");
    }
    if (this.infinite || other.infinite) {
      return complex_infinity;
    }
    return new Complex(
      this.real - other.real,
      this.imag - other.imag
    );
  }

  equals(other) {
    if (this == other) {
      return true;
    }
    if (other == null || !(other instanceof Complex)) {
      return false;
    }
    if (this.infinite && other.infinite) return true;
    if (this.infinite != other.infinite) return false;
    return other.real === this.real && other.imag === this.imag;
  }
}



class Circle {
  constructor(x=0, y=0, r=1) {
    this.center = new Complex(x, y);
    this.radius = r;
  }

  static fromThreePoints(p1, p2, p3) {
    // Credit to https://www.xarg.org/2018/02/create-a-circle-out-of-three-points/
    var x1 = p1.real;
    var y1 = p1.imag;
    var x2 = p2.real;
    var y2 = p2.imag;
    var x3 = p3.real;
    var y3 = p3.imag;
    var a = x1 * (y2 - y3) - y1 * (x2 - x3) + x2 * y3 - x3 * y2;
    var b = (x1 * x1 + y1 * y1) * (y3 - y2) + (x2 * x2 + y2 * y2) * (y1 - y3) + (x3 * x3 + y3 * y3) * (y2 - y1);
    var c = (x1 * x1 + y1 * y1) * (x2 - x3) + (x2 * x2 + y2 * y2) * (x3 - x1) + (x3 * x3 + y3 * y3) * (x1 - x2);
    var x = -b / (2 * a);
    var y = -c / (2 * a);
    return new Circle(x, y, new Complex(x - x1, y - y1).norm());
  }

  contains(z) {
    return z.minus(this.center).normSquared() < this.radius * this.radius;
  }
}

class MobiusTransformation {
  constructor(a, b, c, d) {
    this.a = a;
    this.b = b;
    this.c = c;
    this.d = d;
  }

  static from01inf(z0, z1, zInf) {
    return MobiusTransformation.to01inf(z0, z1, zInf).inverse();
  }

  static to01inf(z0, z1, zInf) {
    if (z0.equals(z1) || z1.equals(zInf) || zInf.equals(z0)) {
      throw new Error("Nonsensical MobiusTransformation");
    }
    if (z0.infinite) {
      return new MobiusTransformation(
        new Complex(),
        zInf.minus(z1),
        new Complex(-1, 0),
        zInf
      );
    }
    if (z1.infinite) {
      return new MobiusTransformation(
        new Complex(1, 0),
        z0.times(-1),
        new Complex(1, 0),
        zInf.times(-1)
      );
    }
    if (zInf.infinite) {
      return new MobiusTransformation(
        new Complex(-1, 0),
        z0,
        new Complex(),
        z0.minus(z1)
      );
    }
    let aa = z1.minus(zInf);
    let bb = z0.times(zInf.minus(z1));
    let cc = z1.minus(z0);
    let dd = zInf.times(z0.minus(z1));
    return new MobiusTransformation(aa, bb, cc, dd);
  }

  static mapThree(s1, s2, s3, d1, d2, d3) {
    let m1 = this.to01inf(s1, s2, s3);
    let m2 = this.from01inf(d1, d2, d3);
    return m2.compose(m1);
  }

  apply(z) {
    return this.a.times(z).plus(this.b).over(this.c.times(z).plus(this.d));
  }

  inverse() {
    return new MobiusTransformation(this.d, this.b.times(-1), this.c.times(-1), this.a);
  }

  compose(other) {
    let aa = this.a.times(other.a).plus(this.b.times(other.c));
    let bb = this.a.times(other.b).plus(this.b.times(other.d));
    let cc = this.c.times(other.a).plus(this.d.times(other.c));
    let dd = this.c.times(other.b).plus(this.d.times(other.d));
    return new MobiusTransformation(aa, bb, cc, dd);
  }

  equals(other) {
    if (this == other) {
      return true;
    }
    if (other == null || !(other instanceof MobiusTransformation)) {
      return false;
    }
    return this.a.equals(other.a) && this.b.equals(other.b) && this.c.equals(other.c) && this.d.equals(other.d);
  }
}

class Gasket {
  constructor(c1, c2, c3) {
    this.circles = [];
    this.circleIDs = new Map();
    this.tangencies = new Map();
    this.addCircle(c1);
    this.addCircle(c2);
    this.addCircle(c3);
    let t1 = this.getTangency(c1, c2);
    let t2 = this.getTangency(c2, c3);
    let t3 = this.getTangency(c3, c1);
    let outer = this.outerCircleFromTangencies(t1, t2, t3);
    this.addCircle(outer);
    this.generate(c3, c2, outer, 0);
    this.generate(c3, outer, c1, 0);
    this.generate(outer, c2, c1, 0);
    this.generate(c1, c2, c3, 0);
  }

  generate(c1, c2, c3, depth) {
    // If any of the circles have radii less than the minimum, break out.
    if (c1.radius < MINIMUM_RADIUS || c2.radius < MINIMUM_RADIUS || c3.radius < MINIMUM_RADIUS || depth >= MAX_DEPTH) {
      return;
    }
    let t1 = this.getTangency(c1, c2);
    let t2 = this.getTangency(c2, c3);
    let t3 = this.getTangency(c3, c1);
    var inner;
    try {
      inner = this.innerCircleFromTangencies(t1, t2, t3);
    } catch (Error) {
      return;
    }
    this.addCircle(inner);
    this.generate(c1, c2, inner, depth + 1);
    this.generate(c1, inner, c3, depth + 1);
    this.generate(inner, c2, c3, depth + 1);
  }

  innerCircleFromTangencies(t1, t2, t3) {
    let fromStandard = MobiusTransformation.mapThree(standard_tangency_1, standard_tangency_2, standard_tangency_3, t1, t2, t3);
    let p1 = fromStandard.apply(inner_tangency_1);
    let p2 = fromStandard.apply(inner_tangency_2);
    let p3 = fromStandard.apply(inner_tangency_3);
    return Circle.fromThreePoints(p1, p2, p3);
  }

  outerCircleFromTangencies(t1, t2, t3) {
    let fromStandard = MobiusTransformation.mapThree(standard_tangency_1, standard_tangency_2, standard_tangency_3, t1, t2, t3);
    let p1 = fromStandard.apply(outer_tangency_1);
    let p2 = fromStandard.apply(outer_tangency_2);
    let p3 = fromStandard.apply(outer_tangency_3);
    return Circle.fromThreePoints(p1, p2, p3);
  }

  getTangency(c1, c2) {
    let id1 = this.getCircleID(c1);
    let id2 = this.getCircleID(c2);
    let tangencyID = Math.min(id1, id2).toString() + '-' + Math.max(id1, id2).toString();
    if (!this.tangencies.has(tangencyID)) {
      this.tangencies.set(tangencyID, this.findTangency(c1, c2));
    }
    return this.tangencies.get(tangencyID);
  }

  getCircleID(c) {
    this.addCircle(c);
    return this.circleIDs.get(c);
  }

  addCircle(c) {
    if (!this.circleIDs.has(c)) {
      this.circleIDs.set(c, this.circles.length);
      this.circles.push(c);
    }
  }

  findTangency(c1, c2) {
    // In general, we want to find the vector from c1.center to c2.center, normalize it, and then
    // step c1.radius along it. However, there is an edge case if c2 contains c1, since the
    // tangency won't fall between the centers. If this happens, the easiest thing to do is to
    // call this method again with the parameters swapped.
    if (c2.radius > c1.radius) {
      return this.findTangency(c2, c1);
    } else {
      let c2c = c2.center.minus(c1.center);
      return c1.center.plus(c2c.unit().times(c1.radius));
    }
  }
}

let complex_infinity;
let sqrt_3_over_2 = 0.5 * Math.sqrt(3);

// The tangencies of the standard circles
let standard_tangency_1 = new Complex(0, -0.5);
let standard_tangency_2 = new Complex(0.5 * sqrt_3_over_2, 0.25);
let standard_tangency_3 = new Complex(-0.5 * sqrt_3_over_2, 0.25);

// The tangencies of the inner circle with the standard circles
let inner_tangency_1 = standard_tangency_1.conjugate().times(2 - Math.sqrt(3));
let inner_tangency_2 = standard_tangency_2.conjugate().times(2 - Math.sqrt(3));
let inner_tangency_3 = standard_tangency_3.conjugate().times(2 - Math.sqrt(3));

let outer_tangency_1 = standard_tangency_1.conjugate().times(2 + Math.sqrt(3));
let outer_tangency_2 = standard_tangency_2.conjugate().times(2 + Math.sqrt(3));
let outer_tangency_3 = standard_tangency_3.conjugate().times(2 + Math.sqrt(3));

let MINIMUM_RADIUS = 0.025;
let MAX_DEPTH = 10;

let alpha = Math.sqrt(sqrt_3_over_2 + 0.75) / (0.5 + sqrt_3_over_2);

