function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

  background(10, 10, 15, 6);
  frameCnt = frameCount % 500;
  generateCircles();
  translate(width / 2, height / 2);
  scale(1, -1); // Flip y-axis for complex plane orientation
  let s = 140; // Scale factor; adjust as needed to fit the view
  stroke(255);
  noFill();
  strokeWeight(2.5);
  circles.forEach((circle) => {
    ellipse(
      circle.center.real * s,
      circle.center.imag * s,
      circle.radius * 2 * s,
      circle.radius * 2 * s
    );
  });
}

function generateCircles() {
  let ghost = new Circle(0, 0.5, 0.5 + sqrt_3_over_2);
  let theta = (frameCnt / 500) * (11.0 + 0.058) * Math.PI / 6.0 + (500 - frameCnt) / 500 * (7.00 - 0.058) * Math.PI / 6.0;
  let cent = new Complex(0, 1);
  let center1 = intersectCircleRay(ghost, theta);
  let r1 = center1.minus(cent).norm() - sqrt_3_over_2;
  let circle1 = new Circle(center1.real, center1.imag, r1);
  let t1 = new Complex(0, 1 + sqrt_3_over_2);
  let t2 = center1.plus(cent.minus(center1).unit().times(r1));
  let t3 = center1.unit().times(1 + sqrt_3_over_2);
  let d1 = outer_tangency_1;
  let d2 = outer_tangency_3;
  let d3 = standard_tangency_3;
  let fromFidgetSpinner = MobiusTransformation.mapThree(d1, d2, d3, t1, t2, t3);
  let p1 = fromFidgetSpinner.apply(standard_tangency_1);
  let p2 = fromFidgetSpinner.apply(standard_tangency_2);
  let p3 = fromFidgetSpinner.apply(new Complex(sqrt_3_over_2 + 0.75, -0.5 - sqrt_3_over_2 * 0.5));
  let circle2 = Circle.fromThreePoints(p1, p2, p3);
  let circle3 = new Circle(0, 1, sqrt_3_over_2);
  let gasket = new Gasket(circle1, circle2, circle3);
  circles = gasket.circles;
  circles.push(new Circle(0, 0, 1 + sqrt_3_over_2));
}

function positiveRoot(a, b, c) {
  if (b * b - 4 * a * c < 0 || a === 0) {
    throw new Error('No roots');
  }
  return (-b + Math.sqrt(b * b - 4 * a * c)) / (2 * a);
}

function intersectCircleRay(circle, theta) {
  let u = new Complex(Math.cos(theta) * alpha, Math.sin(theta));
  let a = 1;
  let b = -2 * (u.real * circle.center.real + u.imag * circle.center.imag);
  let c = circle.center.normSquared() - circle.radius * circle.radius;
  return u.times(positiveRoot(a, b, c));
}

